#include "dummy/verification.hpp"
#include "json_value_verification.hpp"

#pragma warning(push, 0)
#include <nlohmann/json.hpp>

#include <limits>
#include <string>
#include <vector>
#pragma warning(pop)

#define CATCH_CONFIG_MAIN
